// SAFE SSH/SFTP helper for the LIVE Soul Pilates box (server id cmsc9l72y000ghl7iyd87u5ja).
// Never prints the plaintext password. Guards EVERY remote command with a hostname
// assertion that 51.79.226.200 is present, aborting otherwise.
//
// Usage:
//   node sp.js exec  '<remote shell command>'      # run a command (guarded)
//   node sp.js put   <localPath> <remotePath>      # upload a file via sftp
//   node sp.js get   <remotePath>                  # print a remote file to stdout (guarded via exec cat)
'use strict';
const fs = require('node:fs');
const path = require('node:path');
const { createDecipheriv, scryptSync } = require('node:crypto');
const { Client } = require('/opt/nxeon/node_modules/ssh2');
const SftpClient = require('/opt/nxeon/node_modules/ssh2-sftp-client');
const { PrismaClient } = require('/opt/nxeon/node_modules/@prisma/client');

const SERVER_ID = 'cmsc9l72y000ghl7iyd87u5ja';
const EXPECT_IP = '51.79.226.200';

// --- load /opt/nxeon/.env (minimal parser) ---
for (const line of fs.readFileSync('/opt/nxeon/.env', 'utf8').split('\n')) {
  const m = line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.*)\s*$/);
  if (!m) continue;
  let v = m[2];
  if ((v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"))) v = v.slice(1, -1);
  if (!(m[1] in process.env)) process.env[m[1]] = v;
}

function deriveKey() {
  const secret = process.env.AUTH_SECRET;
  if (!secret || !secret.trim()) throw new Error('AUTH_SECRET not set');
  return scryptSync(secret, 'nxeon-byok', 32);
}
function decryptSecret(enc) {
  if (!enc) return null;
  try {
    const [ivB64, tagB64, dataB64] = enc.split(':');
    if (!ivB64 || !tagB64 || !dataB64) return null;
    const d = createDecipheriv('aes-256-gcm', deriveKey(), Buffer.from(ivB64, 'base64'));
    d.setAuthTag(Buffer.from(tagB64, 'base64'));
    return Buffer.concat([d.update(Buffer.from(dataB64, 'base64')), d.final()]).toString('utf8');
  } catch { return null; }
}

async function target() {
  const prisma = new PrismaClient();
  try {
    const s = await prisma.server.findUnique({
      where: { id: SERVER_ID },
      select: { id: true, rootPassword: true, rootPasswordEnc: true, sshPort: true, ipAddress: true,
                dedicatedIp: { select: { address: true } } },
    });
    if (!s) throw new Error('server row not found');
    const password = decryptSecret(s.rootPasswordEnc) ?? s.rootPassword;
    if (!password) throw new Error('no root password');
    const dedicated = !!s.dedicatedIp;
    const host = dedicated ? s.dedicatedIp.address : process.env.PUBLIC_IP;
    const port = dedicated ? 22 : s.sshPort;
    if (host !== EXPECT_IP) {
      // Extra safety: refuse if the resolved host is not the expected live box.
      throw new Error(`resolved host ${host} != expected ${EXPECT_IP}; aborting`);
    }
    return { host, port, password };
  } finally { await prisma.$disconnect(); }
}

function connect(t) {
  return new Promise((resolve, reject) => {
    const conn = new Client();
    conn.on('ready', () => resolve(conn))
        .on('error', reject)
        .connect({ host: t.host, port: t.port, username: 'root', password: t.password, readyTimeout: 20000 });
  });
}

function execRaw(conn, command, timeoutMs = 900000) {
  return new Promise((resolve, reject) => {
    conn.exec(command, (err, stream) => {
      if (err) return reject(err);
      let out = '', erro = '';
      const timer = setTimeout(() => { try { stream.close(); } catch {} reject(new Error('timeout')); }, timeoutMs);
      stream.on('close', (code) => { clearTimeout(timer); resolve({ code, stdout: out, stderr: erro }); })
            .on('data', (d) => out += d.toString('utf8'))
            .stderr.on('data', (d) => erro += d.toString('utf8'));
    });
  });
}

// Guard wrapper: only run the real command if remote hostname -I contains EXPECT_IP.
function guarded(command) {
  return `if hostname -I | tr ' ' '\\n' | grep -qx ${EXPECT_IP}; then :; else echo "GUARD_FAIL: remote is not ${EXPECT_IP}" >&2; exit 99; fi\n${command}`;
}

async function main() {
  const [mode, ...rest] = process.argv.slice(2);
  const t = await target();
  if (mode === 'put') {
    const [local, remote] = rest;
    const sftp = new SftpClient();
    await sftp.connect({ host: t.host, port: t.port, username: 'root', password: t.password, readyTimeout: 20000 });
    try {
      // guard via a quick exec on a parallel channel is not trivial with sftp; verify host already matched EXPECT_IP in target()
      await sftp.put(local, remote);
      process.stdout.write(`PUT_OK ${remote}\n`);
    } finally { await sftp.end(); }
    return;
  }
  const conn = await connect(t);
  try {
    let command;
    if (mode === 'exec') command = guarded(rest[0]);
    else if (mode === 'get') command = guarded(`cat ${JSON.stringify(rest[0])}`);
    else throw new Error('unknown mode: ' + mode);
    const r = await execRaw(conn, command);
    process.stdout.write(r.stdout);
    if (r.stderr) process.stderr.write(r.stderr);
    process.exitCode = r.code === null ? 1 : r.code;
  } finally { conn.end(); }
}
main().catch((e) => { console.error('ERR', e.message); process.exit(1); });

